pub struct Item {
    pub item_type: String,
    pub material: String,
    pub enchantment: u32,
    pub cursed: bool,
}

const PROCESSING_FEE: u64 = 5;

const SWORD_BASE_PREMIUM: u64 = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;

/// The MHPCO price list: the base premium the catalogue lists for one item.
fn base_premium(_item: &Item) -> u64 {
    SWORD_BASE_PREMIUM
}

/// The policy base premium: the sum of all insured items' base premiums.
fn policy_base_premium(items: &[Item]) -> u64 {
    items.iter().map(base_premium).sum()
}

pub fn quote_premium(items: &[Item]) -> u64 {
    let policy_base_premium = policy_base_premium(items);
    let first_insurance_surcharge =
        policy_base_premium * FIRST_INSURANCE_SURCHARGE_PERCENT / 100;
    policy_base_premium + first_insurance_surcharge + PROCESSING_FEE
}
