/// The MHPCO price list: the base premium the catalogue lists for one item.
fn base_premium(item: &Item) -> u64 {
    match item.item_type.as_str() {
        "amulet" => AMULET_BASE_PREMIUM,
        "staff" => STAFF_BASE_PREMIUM,
        "potion" => POTION_BASE_PREMIUM,
        "rune" | "moonstone" => COMPONENT_BASE_PREMIUM,
        _ => SWORD_BASE_PREMIUM,
    }
}

/// The policy base premium: the sum of all insured items' base premiums.
fn policy_base_premium(items: &[Item]) -> u64 {
    items.iter().map(base_premium).sum()
}

